import React from "react";
import Navbar from "../components/Navbar";
import { motion } from "framer-motion";
import { Link } from "react-router-dom";

export default function Pricing() {
  const plans = [
    {
      name: "Individual",
      price: "₹199",
      sub: "per month",
      points: ["Scam check", "UPI/QR verification", "Account safety guidance"],
      highlight: false
    },
    {
      name: "Family Pack",
      price: "₹499",
      sub: "up to 5 members",
      points: [
        "All Individual features",
        "Parents protection",
        "Kids safety guidance"
      ],
      highlight: true,
      badge: "Most Popular"
    },
    {
      name: "Premium",
      price: "₹999",
      sub: "priority support",
      points: ["Emergency help", "Faster replies", "Monthly safety reminders"],
      highlight: false
    }
  ];

  return (
    <div className="min-h-screen bg-gradient-to-b from-gray-50 via-white to-gray-50">
      <Navbar />

      <div className="max-w-6xl mx-auto px-4 py-12">
        <motion.div
          initial={{ opacity: 0, y: 16 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ duration: 0.55, ease: "easeOut" }}
        >
          <h2 className="text-4xl font-black tracking-tight">Plans</h2>
          <p className="text-gray-600 mt-2 text-lg">
            First time users:{" "}
            <span className="font-semibold">₹99 for 1st month</span> 🎉
          </p>

          <div className="grid md:grid-cols-3 gap-5 mt-10">
            {plans.map((p, idx) => (
              <motion.div
                key={p.name}
                initial={{ opacity: 0, y: 18 }}
                animate={{ opacity: 1, y: 0 }}
                transition={{ duration: 0.55, delay: idx * 0.08 }}
                className={`relative bg-white rounded-3xl shadow p-7 border hover:shadow-md transition ${
                  p.highlight ? "border-gray-900" : ""
                }`}
              >
                {p.badge && (
                  <div className="absolute -top-3 left-6 px-3 py-1 rounded-full bg-gray-900 text-white text-xs font-bold">
                    {p.badge}
                  </div>
                )}

                <div className="font-black text-xl">{p.name}</div>

                <div className="mt-3">
                  <div className="text-4xl font-black">{p.price}</div>
                  <div className="text-sm text-gray-600 mt-1">{p.sub}</div>
                </div>

                <ul className="mt-6 space-y-2 text-sm text-gray-700">
                  {p.points.map((x) => (
                    <li key={x} className="flex gap-2">
                      <span>✅</span>
                      <span>{x}</span>
                    </li>
                  ))}
                </ul>

                <div className="mt-7">
                  <Link
                    to="/signup"
                    className={`w-full inline-flex justify-center px-6 py-3 rounded-2xl font-semibold transition active:scale-[0.99] ${
                      p.highlight
                        ? "bg-gray-900 text-white hover:opacity-95"
                        : "border hover:bg-gray-50"
                    }`}
                  >
                    Start with this plan
                  </Link>
                </div>
              </motion.div>
            ))}
          </div>

          <motion.div
            initial={{ opacity: 0, y: 12 }}
            animate={{ opacity: 1, y: 0 }}
            transition={{ duration: 0.55, delay: 0.25 }}
            className="mt-12 bg-white rounded-3xl border p-6"
          >
            <div className="text-lg font-black">Important Note</div>
            <div className="mt-2 text-sm text-gray-700 leading-relaxed">
              ⚠️ CyberRaksha provides guidance and scam verification. We never
              ask for OTP/password and we do not guarantee money recovery.
            </div>
          </motion.div>
        </motion.div>
      </div>
    </div>
  );
}
